// Pure note shaping. No I/O.

export type Note = {
  id: string;
  teamId: string;
  authorId: string;
  title: string;
  body: string;
  version: number;
  createdAt: string;
  updatedAt: string;
  /** Present only on deleted notes. */
  deletedAt?: string;
};

export type NoteRow = {
  seq: number;
  id: string;
  team_id: string;
  author_id: string;
  title: string;
  body: string;
  version: number;
  created_at: string;
  updated_at: string;
  deleted_at: string | null;
};

export type NewNoteInput = { id: string; teamId: string; authorId: string; title: string; body: string };

/** Row -> API shape. Lists exactly the Note schema fields (additionalProperties: false). */
export function toNote(row: NoteRow): Note {
  return {
    id: row.id,
    teamId: row.team_id,
    authorId: row.author_id,
    title: row.title,
    body: row.body,
    version: row.version,
    createdAt: row.created_at,
    updatedAt: row.updated_at,
    ...(row.deleted_at === null ? {} : { deletedAt: row.deleted_at }),
  };
}

/** A brand-new note: version 1, both timestamps equal to `now` (ISO-8601 UTC, ms precision). */
export function newNoteFields(input: NewNoteInput, now: Date): Note {
  const ts = now.toISOString();
  return { ...input, version: 1, createdAt: ts, updatedAt: ts };
}
// Pure If-Match parsing (ADR-0002). No I/O.

/**
 * The version a PATCH expects, from its If-Match header.
 * null  -> precondition required (header missing or `*`): 428.
 * n >= 1 -> the strong ETag `"n"`.
 * 0     -> present but can never match (weak, malformed, a list): compares stale, 412. Versions start at 1.
 */
export function parseIfMatch(header: string | undefined): number | null {
  const h = header?.trim();
  if (h === undefined || h === '' || h === '*') return null;
  const m = /^"(\d+)"$/.exec(h);
  return m ? Number(m[1]) : 0;
}

export const etag = (version: number): string => `"${version}"`;
// Pure input validation. No I/O. Parses unknown JSON once into trusted values.

export type FieldError = { field: string; message: string };
export type Result<T> = { ok: true; value: T } | { ok: false; errors: FieldError[] };

export type NoteCreate = { title: string; body: string };
export type NotePatch = { title?: string; body?: string };

export const TITLE_MAX = 200;
export const BODY_MAX = 100000;

/** Length in Unicode code points (ADR-0003). */
const length = (s: string): number => [...s].length;

/** Fields the server owns; a client may never send them. */
export const READ_ONLY_FIELDS = ['id', 'teamId', 'authorId', 'version', 'createdAt', 'updatedAt', 'deletedAt'];

const isPlainObject = (v: unknown): v is Record<string, unknown> =>
  typeof v === 'object' && v !== null && !Array.isArray(v);

function checkTitle(v: unknown, errors: FieldError[]): string | undefined {
  if (typeof v !== 'string') {
    errors.push({ field: 'title', message: 'must be a string' });
    return undefined;
  }
  const t = v.trim();
  if (length(t) < 1 || length(t) > TITLE_MAX) {
    errors.push({ field: 'title', message: `must be 1-${TITLE_MAX} characters after trimming` });
    return undefined;
  }
  return t;
}

function checkBody(v: unknown, errors: FieldError[]): string | undefined {
  if (typeof v !== 'string') {
    errors.push({ field: 'body', message: 'must be a string' });
    return undefined;
  }
  if (length(v) > BODY_MAX) {
    errors.push({ field: 'body', message: `must be at most ${BODY_MAX} characters` });
    return undefined;
  }
  return v;
}

function unknownFields(input: Record<string, unknown>, allowed: string[], errors: FieldError[]): void {
  for (const k of Object.keys(input)) {
    if (READ_ONLY_FIELDS.includes(k)) errors.push({ field: k, message: 'read-only field' });
    else if (!allowed.includes(k)) errors.push({ field: k, message: 'unknown field' });
  }
}

const notAnObject: FieldError = { field: '$', message: 'request body must be a JSON object' };

export function validateCreate(input: unknown): Result<NoteCreate> {
  if (!isPlainObject(input)) return { ok: false, errors: [notAnObject] };
  const errors: FieldError[] = [];
  unknownFields(input, ['title', 'body'], errors);
  const title = 'title' in input ? checkTitle(input.title, errors) : (errors.push({ field: 'title', message: 'is required' }), undefined);
  const body = 'body' in input ? checkBody(input.body, errors) : '';
  if (errors.length > 0 || title === undefined || body === undefined) return { ok: false, errors };
  return { ok: true, value: { title, body } };
}

export function validatePatch(input: unknown): Result<NotePatch> {
  if (!isPlainObject(input)) return { ok: false, errors: [notAnObject] };
  const errors: FieldError[] = [];
  unknownFields(input, ['title', 'body'], errors);
  const value: NotePatch = {};
  if ('title' in input) { const t = checkTitle(input.title, errors); if (t !== undefined) value.title = t; }
  if ('body' in input) { const b = checkBody(input.body, errors); if (b !== undefined) value.body = b; }
  if (Object.keys(input).length === 0) errors.push({ field: '$', message: 'at least one field is required' });
  return errors.length > 0 ? { ok: false, errors } : { ok: true, value };
}
import { DatabaseSync } from 'node:sqlite';
import { createHash } from 'node:crypto';
import { readFileSync } from 'node:fs';
import { toNote } from './domain/note.ts';
import type { Note, NoteRow } from './domain/note.ts';
import type { NotePatch } from './domain/validation.ts';

// ---- FAULT INJECTION HOOK (single place; read once) ------------------------------------------
// Deliberate defects, enabled by FAULT=<name>, used by scripts/falsify.sh to prove the suite catches them.
// Usage: `if (fault('name')) { ...deliberately wrong behavior... }` at the call sites.
const FAULT = process.env.FAULT ?? '';
export const fault = (name: string): boolean => FAULT !== '' && FAULT === name;
// ----------------------------------------------------------------------------------------------

export type User = { id: string; name: string };
export type TeamRole = { id: string; name: string; role: 'owner' | 'member' };

const SCHEMA_PATH = new URL('../../../spec/schema.sql', import.meta.url);

export const hashToken = (token: string): string => createHash('sha256').update(token).digest('hex');

export type PatchOutcome =
  | { kind: 'updated'; note: Note }
  | { kind: 'stale'; version: number }
  | { kind: 'gone' };

export type Store = ReturnType<typeof openStore>;

export function openStore(path: string = ':memory:') {
  const db = new DatabaseSync(path);
  db.exec(readFileSync(SCHEMA_PATH, 'utf8'));

  const qUser = db.prepare('SELECT id, name FROM users WHERE token_hash = ?');
  const qTeams = db.prepare(
    `SELECT t.id AS id, t.name AS name, m.role AS role FROM memberships m
     JOIN teams t ON t.id = m.team_id WHERE m.user_id = ? ORDER BY t.id`);
  const qMember = db.prepare('SELECT 1 AS ok FROM memberships WHERE team_id = ? AND user_id = ?');
  const qList = db.prepare('SELECT * FROM notes WHERE team_id = ? AND deleted_at IS NULL ORDER BY seq DESC');
  const qArchived = db.prepare('SELECT * FROM notes WHERE team_id = ? AND deleted_at IS NOT NULL ORDER BY seq DESC');
  // Includes deleted notes: callers decide what a deleted note means for them.
  const qVisible = db.prepare(
    `SELECT n.* FROM notes n JOIN memberships m ON m.team_id = n.team_id
     WHERE n.id = ? AND m.user_id = ?`);
  const qById = db.prepare('SELECT * FROM notes WHERE id = ?');
  const qInsert = db.prepare(
    `INSERT INTO notes (id, team_id, author_id, title, body, version, created_at, updated_at)
     VALUES (?, ?, ?, ?, ?, ?, ?, ?)`);
  const qUpdate = db.prepare(
    `UPDATE notes SET title = COALESCE(?, title), body = COALESCE(?, body),
       version = version + 1, updated_at = ? WHERE id = ? AND version = ? AND deleted_at IS NULL`);
  const qDelete = db.prepare('UPDATE notes SET deleted_at = ? WHERE id = ? AND deleted_at IS NULL');
  const qHardDelete = db.prepare('DELETE FROM notes WHERE id = ?');
  const qRestore = db.prepare(
    `UPDATE notes SET deleted_at = NULL, version = version + ?, updated_at = ? WHERE id = ? AND deleted_at IS NOT NULL`);

  return {
    userByToken(token: string): User | null {
      return (qUser.get(hashToken(token)) as User | undefined) ?? null;
    },
    teamsOf(userId: string): TeamRole[] {
      return qTeams.all(userId) as TeamRole[];
    },
    isMember(teamId: string, userId: string): boolean {
      return qMember.get(teamId, userId) !== undefined;
    },
    /** Live notes, or with `archived` only deleted ones, newest first. */
    listNotes(teamId: string, archived = false): Note[] {
      return ((archived ? qArchived : qList).all(teamId) as NoteRow[]).map(toNote);
    },
    /** The note (live or deleted), only if the user is in its team. Otherwise null (same as absent). */
    visibleNote(noteId: string, userId: string): Note | null {
      const row = qVisible.get(noteId, userId) as NoteRow | undefined;
      return row ? toNote(row) : null;
    },
    insertNote(n: Note): void {
      qInsert.run(n.id, n.teamId, n.authorId, n.title, n.body, n.version, n.createdAt, n.updatedAt);
    },
    /** Does the note exist at all (any team, live or deleted)? Only for the leak-403 fault. */
    noteExists(noteId: string): boolean {
      return qById.get(noteId) !== undefined;
    },
    /**
     * Check-and-increment in one statement. When nothing changed, re-read to tell
     * "gone" (404) from "stale" (412, carries the current version).
     */
    patchNote(noteId: string, patch: NotePatch, expectedVersion: number, now: Date): PatchOutcome {
      const res = qUpdate.run(patch.title ?? null, patch.body ?? null, now.toISOString(), noteId, expectedVersion);
      const row = qById.get(noteId) as NoteRow | undefined;
      if (Number(res.changes) > 0) return { kind: 'updated', note: toNote(row!) };
      return row && row.deleted_at === null ? { kind: 'stale', version: row.version } : { kind: 'gone' };
    },
    softDeleteNote(noteId: string, now: Date): void {
      // FAULT hard-delete: the row is removed, so the content is lost and a later restore finds nothing.
      if (fault('hard-delete')) { qHardDelete.run(noteId); return; }
      qDelete.run(now.toISOString(), noteId);
    },
