  // baseline for pre-existing notes
  const pre = {};
  for (const [t, c] of [['team-red', 'alice'], ['team-blue', 'carol']]) for (const arch of [false, true]) {
    const r = await request(base, 'GET', `/teams/${t}/notes${arch ? '?archived=true' : ''}`, { token: TOK[c] });
