      if (n.version !== 1) fail('M', r.desc, `new note version ${n.version}`);
      if (b.obj && b.obj.title !== undefined && r.json.title !== String(b.obj.title).trim()) fail('M', r.desc, `title not stored trimmed: ${JSON.stringify(r.json.title)}`);
