    if (R.chance(0.3)) headers['content-type'] = R.pick(['application/json', 'text/plain', 'application/json; charset=é']);
    if (R.chance(0.3)) headers['if-match'] = R.pick(['*', '"1"', 'W/"1"', '"1","2"']);
